   	 , 	#{boardTitle}
   	 ,  #{boardContent}
   	 ,  #{memberId}
   	    )

INSERT
  INTO
  		TB_ATTACHMENT
  		(
  		FILE_NO
  	  ,	REF_BNO
  	  , ORIGIN_NAME
  	  , CHANGE_NAME
  	  , FILE_PATH
  	  , BOARD_TYPE
  	  , FILE_LEVEL

  		)
 VALUES
 		(
 		SEQ_ANO.NEXTVAL
 	  , #{originName}
 	  , #{changeName}
 	  , #{filePath}
 	  , #{boardType}
 	  , #{fileLevel}
 		)
